window.VOCAB_LWS_META = [{"batch":2,"added":"2026-11-07","lesson":1,"lesson_title":"Glück im Alltag","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 171–175","tips":[{"text":"Das Wort *als* hat mehrere Bedeutungen. Schreiben Sie zu jeder Bedeutung einen Satz.","text_en":"La parola *als* ha diversi significati. Scrivi una frase per ogni significato.","example":"Wann? Als ich drei Jahre alt war, bekam ich mein erstes Haustier.","answer":["Vergleich: Jan ist älter als Julian","Berufsbezeichnung: Er arbeitet als Arzt"],"note":"Tre significati: *als* = quando (un singolo evento nel passato, verbo in fondo), *als* dopo un comparativo = di / che, *als* + professione o ruolo = come. Per qualcosa che nel passato è successo più volte si usa *wenn*, non *als*."}],"count":78},{"batch":3,"added":"2026-11-07","lesson":2,"lesson_title":"Unterhaltung","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 175–179","tips":[{"text":"Schreiben Sie eine kleine Geschichte mit den Wörtern aus der Lektion.","text_en":"Scrivi una breve storia con le parole della lezione.","example":"Meine Geschichte handelt von einem unglaublichen Abenteuer: Ich begegnete in einer grossen Stadt dem Star aus meiner Lieblingsserie. Unglaublich! Ich war optimistisch, dass …","answer":["… ich ein Foto mit ihm machen kann. Ich hatte zwar nicht den Mut, ihn anzusprechen, aber dann kam die grosse Überraschung: Er fragte mich, wo der Bahnhof ist!"],"note":"Una risposta modello; la tua può essere del tutto diversa. In italiano: '… che ho potuto farmi una foto con lui. Non ho avuto il coraggio di parlargli, è vero, ma poi è arrivata la grande sorpresa: mi ha chiesto dov'era la stazione!' Riprende *zwar … aber*, *der Mut* e *die Überraschung* dalla Lektion 1."}],"count":66},{"batch":4,"added":"2026-11-07","lesson":3,"lesson_title":"Gesund bleiben","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 179–183","tips":[{"text":"Lernen Sie typische Wendungen zusammen.","text_en":"Impara insieme le espressioni tipiche.","example":"den Blutdruck messen, Blut abnehmen, das Gewicht prüfen, den Bauch …","answer":["den Bauch untersuchen","jemanden impfen","Medikamente verschreiben","jemanden krankschreiben","ein Gespräch führen","einen Termin vereinbaren","Sport treiben","auf Schokolade verzichten"],"note":"*den Bauch untersuchen* completa la lista del libro (visitare l'addome). Le altre sono coppie di parole di questa lezione da imparare come un'unica unità: farsi vaccinare, prescrivere medicinali, mettere in malattia qualcuno, avere un colloquio, fissare un appuntamento, fare sport, rinunciare al cioccolato."}],"count":68},{"batch":1,"added":"2026-11-06","lesson":4,"lesson_title":"Sprachen","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 184–187","tips":[{"text":"Im Deutschen enden viele Sprachen auf «-isch». Schreiben Sie.","text_en":"In tedesco molte lingue finiscono in «-isch». Scrivine alcune.","example":"Griechisch, Französisch, …","answer":["Englisch","Spanisch","Italienisch","Portugiesisch","Russisch","Polnisch","Türkisch","Arabisch","Chinesisch","Japanisch","Ungarisch","Albanisch"],"note":"I nomi delle lingue sono neutri e di solito non hanno articolo: *Ich lerne Spanisch.* Non tutte le lingue finiscono in *-isch*: *Deutsch*, *Hindi* e *Swahili* no."}],"count":60},{"batch":5,"added":"2026-11-09","lesson":5,"lesson_title":"Eine Arbeit finden","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 188–191","tips":[{"text":"Notieren Sie einen Beruf. Bilden Sie mit seinen Buchstaben einen Satz.","text_en":"Scrivi una professione. Forma una frase con le sue lettere.","example":"Maler: *M*ein *A*rzt *l*iest *e*inen *R*eiseführer.","answer":["Arzt: Anna ruft zwei Taxis","Lehrer: Lara erklärt heute Ronja einen Roman"],"note":"Ogni parola comincia con la lettera successiva della professione. Va bene qualsiasi frase che funzioni."}],"count":53},{"batch":6,"added":"2026-11-09","lesson":6,"lesson_title":"Dienstleistung","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 191–195","tips":[{"text":"Bilden Sie mit den Buchstaben von einem langen Wort neue Wörter.","text_en":"Forma nuove parole con le lettere di una parola lunga.","example":"Bedienungsanleitung: laut, Dienstag, Tal, …","answer":["Bad","Geld","Insel","Nadel","Lied","Sieg","Tanne","Leben"],"note":"Usa ogni lettera di *Bedienungsanleitung* al massimo tante volte quante compare nella parola."}],"count":66},{"batch":7,"added":"2026-11-09","lesson":7,"lesson_title":"Rund ums Wohnen","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 196–200","tips":[{"text":"Leiten Sie unbekannte Wörter von bekannten Wörtern ab.","text_en":"Ricava le parole sconosciute da parole che conosci.","example":"unaufmerksam = nicht aufmerksam","answer":["unverständlich = nicht verständlich","ungemütlich = nicht gemütlich","friedlich = ohne Streit, voller Frieden","der Stadtrand = der Rand der Stadt","das Fernsehverbot = das Verbot, fernzusehen"],"note":"*un-* trasforma un aggettivo nel suo contrario; un nome composto si spiega con la sua ultima parte."}],"count":67}];
